/**
 * Build the two loadable halves from src/:
 *   - src/host/index.js   → dist/index.js   (Node ESM bundle for the host process)
 *   - src/client/index.js → dist/client.js   (browser bundle wrapped for the DSH
 *     client module loader: window.__ModuleLoader__.load({ id, factory }))
 *
 * Plain JavaScript + esbuild; no TypeScript. React stays external for the
 * client because the loader injects it through `require('react')`.
 */
import { mkdir, writeFile } from 'node:fs/promises';
import { build } from 'esbuild';

const HOST_BANNER =
  '/* AUTO-GENERATED by scripts/build.mjs — do not edit. Source: src/host/*.js. Run `pnpm run build`. */';
const CLIENT_BANNER =
  '/* AUTO-GENERATED by scripts/build.mjs — do not edit. Source: src/client/* + src/shared/*. Run `pnpm run build`. */';

await mkdir('dist', { recursive: true });

async function buildHost() {
  await build({
    entryPoints: ['src/host/index.js'],
    outfile: 'dist/index.js',
    bundle: true,
    format: 'esm',
    platform: 'node',
    target: ['node20'],
    legalComments: 'none',
    banner: { js: HOST_BANNER },
    logLevel: 'warning',
  });
  console.log('built dist/index.js');
}

async function buildClient() {
  const result = await build({
    entryPoints: ['src/client/index.js'],
    bundle: true,
    write: false,
    format: 'cjs',
    platform: 'browser',
    target: ['es2020'],
    external: ['react'],
    legalComments: 'none',
    logLevel: 'warning',
  });
  const body = result.outputFiles[0].text.replace(/\n+$/, '');
  const wrapped = [
    CLIENT_BANNER,
    'window.__ModuleLoader__.load({',
    "  id: 'dsh-product-design',",
    '  factory(require) {',
    '    var module = { exports: {} };',
    '    var exports = module.exports;',
    body,
    '    return module.exports;',
    '  },',
    '});',
    '',
  ].join('\n');
  await writeFile('dist/client.js', wrapped, 'utf8');
  console.log(`built dist/client.js (${wrapped.length} bytes)`);
}

await buildHost();
await buildClient();
